  // A goVersion is a Go language version string of the form "go1.%d"
  // where d is the minor version number. goVersion strings don't
  // contain release numbers ("go1.20.1" is not a valid goVersion).
  export class goVersion {
    public constructor(public value: string) {}

    // isValid reports whether v is a valid Go version.
    public isValid(): boolean {
      return this.value !== "";
    }

    // cmp returns -1, 0, or +1 depending on whether x < y, x == y, or x > y,
    // interpreted as Go versions.
    public cmp(y: goVersion): number {
      return compareGoVersions(this.value, y.value);
    }

    public String(): string { return this.value; }
  }

  // asGoVersion returns v as a goVersion (e.g., "go1.20.1" becomes "go1.20").
  // If v is not a valid Go version, the result is the empty string.
  export function asGoVersion(v: string): goVersion {
    const m = /^go(\d+)\.(\d+)/.exec(v);
    if (!m) {
      return new goVersion("");
    }
    return new goVersion(`go${m[1]}.${m[2]}`);
  }

  function compareGoVersions(x: string, y: string): number {
    const parse = (v: string): [number, number] => {
      const m = /^go(\d+)\.(\d+)/.exec(v);
      return [globalThis.Number(m?.[1] ?? 0), globalThis.Number(m?.[2] ?? 0)];
    };
    const [xMaj, xMin] = parse(x);
    const [yMaj, yMin] = parse(y);
    if (xMaj !== yMaj) return xMaj < yMaj ? -1 : 1;
    if (xMin !== yMin) return xMin < yMin ? -1 : 1;
    return 0;
  }

  // Go versions that introduced language changes
  export const go1_9 = asGoVersion("go1.9");
  export const go1_13 = asGoVersion("go1.13");
  export const go1_14 = asGoVersion("go1.14");
  export const go1_17 = asGoVersion("go1.17");
  export const go1_18 = asGoVersion("go1.18");
  export const go1_20 = asGoVersion("go1.20");
  export const go1_21 = asGoVersion("go1.21");
  export const go1_22 = asGoVersion("go1.22");
  export const go1_23 = asGoVersion("go1.23");
  export const go1_26 = asGoVersion("go1.26");
  export const go1_27 = asGoVersion("go1.27");

