  function parseGoIntLiteral(value: string): bigint {
    const text = value.replace(/_/g, "");
    if (/^0[0-7]+$/.test(text)) {
      return globalThis.BigInt(`0o${text.slice(1)}`);
    }
    return globalThis.BigInt(text);
  }

