    const text = value.replace(/_/g, "");
    const hex = /^0[xX]([0-9a-fA-F]*)(?:\.([0-9a-fA-F]*))?[pP]([+-]?[0-9]+)$/.exec(text);
    if (hex === null) {
      return globalThis.Number(text);
    }
    const whole = hex[1] || "0";
    const frac = hex[2] || "";
    const exponent = globalThis.Number(hex[3]);
    const wholeValue = globalThis.Number.parseInt(whole, 16);
    let fracValue = 0;
    for (let index = 0; index < frac.length; index++) {
      fracValue += globalThis.Number.parseInt(frac[index] ?? "0", 16) / 16 ** (index + 1);
    }
    return (wholeValue + fracValue) * 2 ** exponent;
