            // (Ideally we would use the //build tag itself.)
            (this as unknown as { errorf: (at: unknown, code: unknown, format: string, ...args: unknown[]) => void }).errorf(nameIdent, "TooNew", "file requires newer Go version %v (application built with %v)", fileVersion, go_types_version.go_current);
