  installPendingCheckerMethods(Checker);

  // NewChecker returns a new [Checker] instance for a given package.
  // [Package] files may be added incrementally via checker.Files.
  export function NewChecker(conf: go_types_api.Config | null, fset: unknown, pkg: go_types_package.Package, info: go_types_api.Info | null): Checker {
    // make sure we have a configuration
    if (conf === null) {
      conf = newDefaultConfig();
    }

    // make sure we have an info struct
    if (info === null) {
      info = newDefaultInfo();
    }

    // Note: clients may call NewChecker with the Unsafe package, which is
    // globally shared and must not be mutated. Therefore NewChecker must not
    // mutate *pkg.
    //
    // (previously, pkg.goVersion was mutated here: go.dev/issue/61212)

    return new Checker(conf, fset, pkg, info);
  }

