namespace go_types_union {
  // Copyright 2021 The Go Authors. All rights reserved.
  // Use of this source code is governed by a BSD-style
  // license that can be found in the LICENSE file.

  // A Union represents a union of terms embedded in an interface.
  export class Union implements go_types_type.Type {
    public constructor(
      public terms: Term[] // list of syntactical terms (not a canonicalized termlist)
    ) {}

    public Len(): number { return this.terms.length; }
    public Term(i: number): Term { return this.terms[i]!; }

    public Underlying(): go_types_type.Type { return this; }
    public String(): string { return go_types_typestring.TypeString(this, null); }
  }

  // NewUnion returns a new [Union] type with the given terms.
  // It is an error to create an empty union; they are syntactically not possible.
  export function NewUnion(terms: Term[]): Union {
    if (terms.length === 0) {
      throw new globalThis.Error("empty union");
    }
    return new Union(terms);
  }

  // A Term represents a term in a [Union].
  export class Term extends go_types_typeterm.term {
    public constructor(tilde: boolean, typ: go_types_type.Type) {
      super(tilde, typ);
    }

    public Tilde(): boolean { return this.tilde; }
    public Type(): go_types_type.Type { return this.typ!; }
    public String(): string { return super.String(); }
  }

  // NewTerm returns a new union term.
  export function NewTerm(tilde: boolean, typ: go_types_type.Type): Term { return new Term(tilde, typ); }

  // Avoid excessive type-checking times due to quadratic termlist operations.
  export const maxTermCount = 100;

  // parseUnion parses uexpr as a union of expressions.
  // The result is a Union type, or Typ[Invalid] for some errors.
  export function parseUnion(check: go_types_check.Checker, uexpr: unknown): go_types_type.Type {
    const [blist, tlist] = flattenUnion([], uexpr);
    go_types_util.assert(blist.length === tlist.length - 1);

    const terms: Term[] = [];

    let u: go_types_type.Type = go_types_universe.Typ[go_types_basic.BasicKind.Invalid]!;
    for (let i = 0; i < tlist.length; i++) {
      const x = tlist[i]!;
      const trm = parseTilde(check, x);
      if (tlist.length === 1 && !trm.tilde) {
        // Single type. Ok to return early because all relevant
        // checks have been performed in parseTilde (no need to
        // run through term validity check below).
        return trm.typ!; // typ already recorded through check.typ in parseTilde
      }
      if (terms.length >= maxTermCount) {
        if (go_types_predicates.isValid(u)) {
          check.errorf(x, "InvalidUnion", "cannot handle more than %d union terms (implementation limitation)", maxTermCount);
          u = go_types_universe.Typ[go_types_basic.BasicKind.Invalid]!;
        }
      } else {
        terms.push(trm);
        u = new Union(terms);
      }

      if (i > 0) {
        (check as unknown as { recordTypeAndValue: (x: unknown, mode: unknown, typ: go_types_type.Type, val: unknown) => void }).recordTypeAndValue(blist[i - 1]!, go_types_operand.typexpr, u, null);
      }
    }

    if (!go_types_predicates.isValid(u)) {
      return u;
    }

    // Check validity of terms.
    // Do this check later because it requires types to be set up.
    // Note: This is a quadratic algorithm, but unions tend to be short.
    check.later(() => {
      for (let i = 0; i < terms.length; i++) {
        const t = terms[i]!;
        if (!go_types_predicates.isValid(t.typ)) {
          continue;
        }

        const u = t.typ!.Underlying();
        const f = u instanceof go_types_interface.Interface ? u : null;
        if (t.tilde) {
          if (f !== null) {
            check.errorf(tlist[i]!, "InvalidUnion", "invalid use of ~ (%s is an interface)", t.typ);
            continue; // don't report another error for t
          }

          if (!go_types_predicates.Identical(u, t.typ)) {
            check.errorf(tlist[i]!, "InvalidUnion", "invalid use of ~ (underlying type of %s is %s)", t.typ, u);
            continue;
          }
        }

        // Stand-alone embedded interfaces are ok and are handled by the single-type case
        // in the beginning. Embedded interfaces with tilde are excluded above. If we reach
        // here, we must have at least two terms in the syntactic term list (but not necessarily
        // in the term list of the union's type set).
        if (f !== null) {
          const tset = f.typeSet();
          switch (true) {
            case tset.NumMethods() !== 0:
              check.errorf(tlist[i]!, "InvalidUnion", "cannot use %s in union (%s contains methods)", t, t);
              break;
            case t.typ === go_types_universe.universeComparable.Type():
              check.error(tlist[i]!, "InvalidUnion", "cannot use comparable in union");
              break;
            case tset.comparable:
              check.errorf(tlist[i]!, "InvalidUnion", "cannot use %s in union (%s embeds comparable)", t, t);
              break;
          }
          continue; // terms with interface types are not subject to the no-overlap rule
        }

        // Report overlapping (non-disjoint) terms such as
        // a|a, a|~a, ~a|~a, and ~a|A (where under(A) == a).
        const j = overlappingTerm(terms.slice(0, i), t);
        if (j >= 0) {
          check.softErrorf(tlist[i]!, "InvalidUnion", "overlapping terms %s and %s", t, terms[j]!);
        }
      }
    }).describef(uexpr as { Pos: () => go_types_token.Pos }, "check term validity %s", uexpr);

    return u;
  }

  export function parseTilde(check: go_types_check.Checker, tx: unknown): Term {
    let x = tx;
    let tilde = false;
    const op = x as { Op?: unknown; op?: unknown; X?: unknown; expr?: unknown } | null;
    if (op !== null && op !== undefined && (op.Op === "~" || op.op === TokenKind.Tilde)) {
      x = op.X ?? op.expr;
      tilde = true;
    }
    let typ = (check as unknown as { typ: (x: unknown) => go_types_type.Type }).typ(x);
    // Embedding stand-alone type parameters is not permitted (go.dev/issue/47127).
    // We don't need this restriction anymore if we make the underlying type of a type
    // parameter its constraint interface: if we embed a lone type parameter, we will
    // simply use its underlying type (like we do for other named, embedded interfaces),
    // and since the underlying type is an interface the embedding is well defined.
    if (go_types_predicates.isTypeParam(typ)) {
      if (tilde) {
        check.errorf(x, "MisplacedTypeParam", "type in term %s cannot be a type parameter", tx);
      } else {
        check.error(x, "MisplacedTypeParam", "term cannot be a type parameter");
      }
      typ = go_types_universe.Typ[go_types_basic.BasicKind.Invalid]!;
    }
    const trm = NewTerm(tilde, typ);
    if (tilde) {
      (check as unknown as { recordTypeAndValue: (x: unknown, mode: unknown, typ: go_types_type.Type, val: unknown) => void }).recordTypeAndValue(tx, go_types_operand.typexpr, new Union([trm]), null);
    }
    return trm;
  }

  // overlappingTerm reports the index of the term x in terms which is
  // overlapping (not disjoint) from y. The result is < 0 if there is no
  // such term. The type of term y must not be an interface, and terms
  // with an interface type are ignored in the terms list.
  export function overlappingTerm(terms: Term[], y: Term): number {
    go_types_util.assert(!go_types_predicates.IsInterface(y.typ!));
    for (let i = 0; i < terms.length; i++) {
      const x = terms[i]!;
      if (go_types_predicates.IsInterface(x.typ!)) {
        continue;
      }
      // disjoint requires non-nil, non-top arguments,
      // and non-interface types as term types.
      if (go_types_check.debug) {
        if (x === null || x.typ === null || y === null || y.typ === null) {
          throw new globalThis.Error("empty or top union term");
        }
      }
      if (!x.disjoint(y)) {
        return i;
      }
    }
    return -1;
  }

  // flattenUnion walks a union type expression of the form A | B | C | ...,
  // extracting both the binary exprs (blist) and leaf types (tlist).
  export function flattenUnion(list: unknown[], x: unknown): [unknown[], unknown[]] {
    let blist: unknown[] = [];
    let tlist: unknown[] = list;
    const o = x as { Op?: unknown; op?: unknown; X?: unknown; Y?: unknown; left?: unknown; right?: unknown } | null;
    if (o !== null && o !== undefined && (o.Op === "|" || o.op === TokenKind.Or)) {
      [blist, tlist] = flattenUnion(list, o.X ?? o.left);
      blist.push(o);
      x = o.Y ?? o.right;
    }
    tlist.push(x);
    return [blist, tlist];
  }
}

