  // Example: for m := range t.Methods() { ... }
  go_types_interface.Interface.prototype.Methods = function Methods(): Seq<go_types_object.Func> {
    return (yield_: (m: go_types_object.Func) => boolean): void => {
      for (let i = 0; i < this.NumMethods(); i++) {
        if (!yield_(this.Method(i))) {
          break;
        }
      }
    };
  };

